{"code":"def transform(grid):
    g=[r[:] for r in grid]
    pts={}
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v:
                pts[v]=(r,c)
    # triangular configuration: apex and right base vertically aligned
    if 1 in pts and 8 in pts and 2 in pts:
        a=pts[1]; b=pts[8]; c=pts[2]
        if b[0]==c[0] and a[1]==c[1] and b[1]<c[1]:
            n=b[0]-a[0]; d=round(3*n/8)
            g[a[0]+d][a[1]-d]=1
            g[b[0]-d][b[1]+d]=8
            g[c[0]-d][c[1]-d]=2
            g[a[0]+d//2][a[1]-d//2]=5
    else:
        # analogous arbitrary labels: top, bottom-left, bottom-right
        non=[]
        for r,row in enumerate(g):
            for c,v in enumerate(row):
                if v: non.append((r,c,v))
        if len(non)==3:
            top=next((x for x in non if all(x[0]<=y[0] for y in non)),None)
            base=[x for x in non if x!=top]
            if top and len(base)==2 and base[0][0]==base[1][0] and top[1]==max(x[1] for x in base):
                bl=min(base,key=lambda x:x[1]); br=max(base,key=lambda x:x[1]); n=bl[0]-top[0]; d=round(3*n/8)
                g[top[0]+d][top[1]-d]=top[2]; g[bl[0]-d][bl[1]+d]=bl[2]; g[br[0]-d][br[1]-d]=br[2]; g[top[0]+d//2][top[1]-d//2]=5
    return g"}

